use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs};
const R:&str="/home/ubuntu/src/zopro-perf-work/direct-ref-pack";
fn hash(x:&[u8])->String{format!("{:x}",Sha256::digest(x))}
fn u64at(x:&[u8],i:usize)->u64{u64::from_le_bytes(x[i..i+8].try_into().unwrap())}
fn u32at(x:&[u8],i:usize)->u32{u32::from_le_bytes(x[i..i+4].try_into().unwrap())}
fn u16at(x:&[u8],i:usize)->u16{u16::from_le_bytes(x[i..i+2].try_into().unwrap())}
fn sections(x:&[u8])->BTreeMap<String,(u64,&[u8])>{
    assert_eq!(&x[..6],b"\x7fELF\x02\x01");let start=u64at(x,40)as usize;let size=u16at(x,58)as usize;let count=u16at(x,60)as usize;let names=u16at(x,62)as usize;assert_eq!(size,64);assert!(start+count*size<=x.len());
    let h=&x[start+names*size..start+(names+1)*size];let off=u64at(h,24)as usize;let n=u64at(h,32)as usize;let strings=&x[off..off+n];let mut result=BTreeMap::new();
    for i in 0..count{let h=&x[start+i*size..start+(i+1)*size];if u32at(h,4)==8{continue}let pos=u32at(h,0)as usize;let name=&strings[pos..];let end=name.iter().position(|b|*b==0).unwrap();let name=std::str::from_utf8(&name[..end]).unwrap();let off=u64at(h,24)as usize;let n=u64at(h,32)as usize;assert!(off+n<=x.len());result.insert(name.to_owned(),(u64at(h,16),&x[off..off+n]));}result
}
fn main(){
    let old=fs::read(format!("{R}/frozen-probe")).unwrap();let new=fs::read(format!("{R}/fresh-probe")).unwrap();let ids:Value=serde_json::from_slice(&fs::read(format!("{R}/probe-artifacts.json")).unwrap()).unwrap();assert_eq!(hash(&old),ids["frozen"]["sha256"].as_str().unwrap());assert_eq!(hash(&new),ids["fresh"]["sha256"].as_str().unwrap());let f=sections(&old);let n=sections(&new);let mut same=vec![];
    for name in[".text",".rodata",".data",".rela.dyn"]{assert_eq!(f[name],n[name]);same.push(json!({"section":name,"virtual_address":f[name].0,"bytes":f[name].1.len(),"sha256":hash(f[name].1),"identical":true}));}
    let mut relocations=BTreeMap::new();let entries=f[".rela.dyn"].1;assert_eq!(entries.len()%24,0);for e in entries.chunks_exact(24){if u64at(e,8)as u32==8{relocations.insert(u64at(e,0),u64at(e,16));}}
    let ro=f[".rodata"].1;let ro_va=f[".rodata"].0;let rel_va=f[".data.rel.ro"].0;assert_eq!(rel_va,n[".data.rel.ro"].0);let mut a=f[".data.rel.ro"].1.to_vec();let mut b=n[".data.rel.ro"].1.to_vec();assert_eq!(a.len(),b.len());let mut locations=vec![];
    for i in 0..a.len(){if a[i]==b[i]{continue}assert!(i>=16);let start=i-16;assert_eq!(&a[start..start+16],&b[start..start+16]);let raw=u64at(&a,start);let ptr=if raw==0{relocations[&(rel_va+start as u64)]}else{raw};let len=u64at(&a,start+8)as usize;let pos=ptr.checked_sub(ro_va).unwrap()as usize;assert!(pos+len<=ro.len());let file=std::str::from_utf8(&ro[pos..pos+len]).unwrap();assert!(file.ends_with(".rs"));assert_eq!(u32at(&a,start+20),u32at(&b,start+20));locations.push(json!({"section_offset":start,"file":file,"frozen_line":u32at(&a,start+16),"fresh_line":u32at(&b,start+16),"column":u32at(&a,start+20)}));for j in 16..20{a[start+j]=0;b[start+j]=0;}}
    assert_eq!(a,b);assert_eq!(locations.len(),20);let plan:Value=serde_json::from_slice(&fs::read(format!("{R}/capture-plan-final.json")).unwrap()).unwrap();let steps=plan["steps"].as_array().unwrap();
    for size in[200,352]{for block in 0..31{let a=steps.iter().find(|s|s["name"]==format!("b{block}-g2-prefix-{size}-frozen")).unwrap();let b=steps.iter().find(|s|s["name"]==format!("b{block}-g2-prefix-{size}-fresh")).unwrap();assert_eq!(a["environment"],b["environment"]);let x=a["argv"].as_array().unwrap();let y=b["argv"].as_array().unwrap();assert_eq!(&x[..3],&y[..3]);assert_eq!(&x[4..],&y[4..]);}}
    let value=json!({"scope":"offline direct ELF64 reads of exact restored pre-capture binaries; no timing or process rerun","equal_sections":same,"data_rel_ro_equal_after_masking_only_20_source_line_fields":true,"changed_source_locations":locations,"G2_all62_command_pairs_identical_except_binary_path":true,"G2_all62_environments_equal":true,"whole_executables_equal":false,"postcapture_tool_rewrite_restored_exactly":"control-restoration.json","original_offline_reader_failure":"control-layout-audit.log: PIE file pointers require RELATIVE relocation addends; no capture repeated","G2_control_gap":"fresh/frozen3.11x/3.18x, outputs/capacities equal; not a candidate speedup","cause":"unresolved; identical code/constants/data/relative-relocation sections do not isolate runtime/address-layout/environmental effects","no_timing_repeat":true});fs::write(format!("{R}/control-layout-audit-v2.json"),serde_json::to_vec_pretty(&value).unwrap()).unwrap();println!("ExactoriginalOFFimages: text/rodata/data/rela.dyn identical; data.rel.ro only20 source-location lines differ;G2controlgapunresolved");
}
